#!/usr/bin/env python3
"""Parse Taylor Swift tour dates from downloaded Wikipedia HTML files."""

from html.parser import HTMLParser
import re, json

class TableExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tables = []
        self.current_table = []
        self.current_row = []
        self.current_cell = ''
        self.in_table = False
        self.in_row = False
        self.in_cell = False
        self.depth = 0
        self.skip_nested = 0

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag == 'table':
            cls = attrs_dict.get('class', '')
            if 'wikitable' in cls or 'sortable' in cls:
                if not self.in_table:
                    self.in_table = True
                    self.current_table = []
                    self.depth = 1
                else:
                    self.depth += 1
                    self.skip_nested += 1
        if self.in_table and not self.skip_nested:
            if tag == 'tr':
                self.in_row = True
                self.current_row = []
            if tag in ('td', 'th'):
                self.in_cell = True
                self.current_cell = ''

    def handle_endtag(self, tag):
        if self.in_table:
            if tag in ('td', 'th') and self.in_cell and not self.skip_nested:
                self.in_cell = False
                # Clean up text
                text = self.current_cell.strip()
                text = re.sub(r'\s+', ' ', text)
                self.current_row.append(text)
            if tag == 'tr' and self.in_row and not self.skip_nested:
                self.in_row = False
                if self.current_row:
                    self.current_table.append(self.current_row)
            if tag == 'table':
                if self.skip_nested > 0:
                    self.skip_nested -= 1
                else:
                    self.in_table = False
                    if self.current_table:
                        self.tables.append(self.current_table)
                self.depth -= 1

    def handle_data(self, data):
        if self.in_cell and not self.skip_nested:
            self.current_cell += data

def extract_tables(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        html = f.read()
    parser = TableExtractor()
    parser.feed(html)
    return parser.tables

def find_date_table(tables, year_keyword):
    """Find the table with tour dates for a given year keyword in headers."""
    for table in tables:
        if len(table) > 1:
            headers = table[0]
            header_text = ' '.join(headers).lower()
            if any(k in header_text for k in ['date', 'city', 'venue']) and year_keyword.lower() in header_text:
                return table
    return None

def find_all_date_tables(tables):
    """Find all tables that look like tour date tables."""
    result = []
    for table in tables:
        if len(table) > 2:
            headers = table[0]
            header_text = ' '.join(headers).lower()
            if ('date' in header_text and ('city' in header_text or 'venue' in header_text) 
                and 'award' not in header_text and 'organization' not in header_text
                and 'guitar' not in header_text):
                result.append(table)
    return result

def clean_text(t):
    """Remove Wikipedia artifacts."""
    t = re.sub(r'\[.*?\]', '', t)  # Remove footnotes like [a], [b]
    t = re.sub(r'\(.*?\)', '', t)  # Remove parenthetical notes
    t = re.sub(r'mw-parser-output.*?N/a', '', t)  # Remove mw artifacts
    t = t.replace('—', '').replace('N/a', '').strip()
    t = re.sub(r'\s+', ' ', t).strip()
    return t

def parse_fearless_tour(tables):
    """Parse Fearless Tour tables (2009 and 2010)."""
    concerts = []

    for table in tables:
        if len(table) < 5:
            continue
        headers = table[0]
        header_text = ' '.join(headers).lower()
        if 'date' not in header_text or 'venue' not in header_text:
            continue

        # Determine the year from headers
        year_match = re.search(r'date \((\d{4})\)', header_text)
        if not year_match:
            continue
        base_year = int(year_match.group(1))

        # Find column indices
        date_col = 0
        city_col = 1
        country_col = None
        venue_col = None

        for i, h in enumerate(headers):
            h_lower = h.lower()
            if 'country' in h_lower:
                country_col = i
            elif 'venue' in h_lower:
                venue_col = i

        if venue_col is None:
            continue

        last_city = ''
        last_country = ''
        last_venue = ''

        for row in table[1:]:
            if len(row) < 2:
                continue

            # Skip total rows
            if row[0].startswith('Total'):
                continue

            # Get date
            date_str = clean_text(row[date_col])
            if not date_str:
                continue

            # Parse month and day
            date_match = re.match(r'(\w+)\s+(\d+)', date_str)
            if not date_match:
                continue

            month_str = date_match.group(1)
            day = int(date_match.group(2))

            months = {'January':1,'February':2,'March':3,'April':4,'May':5,'June':6,
                      'July':7,'August':8,'September':9,'October':10,'November':11,'December':12}
            month = months.get(month_str)
            if not month:
                continue

            year = base_year
            iso_date = f"{year:04d}-{month:02d}-{day:02d}"

            # Get city
            if len(row) > city_col:
                city = clean_text(row[city_col])
                if city:
                    last_city = city

            # Get country
            if country_col is not None and len(row) > country_col:
                country = clean_text(row[country_col])
                if country:
                    last_country = country

            # Get venue
            venue_start = venue_col if country_col is None else venue_col
            if len(row) > venue_start:
                venue = clean_text(row[venue_start])
                if venue:
                    last_venue = venue

            if last_city and last_venue:
                country = last_country if last_country else 'United States'
                concerts.append({
                    'date': iso_date,
                    'tour': 'Fearless Tour',
                    'country': country,
                    'city': last_city,
                    'venue': last_venue
                })

    return concerts

def parse_generic_tour(tables, tour_name):
    """Parse a tour with standard table format."""
    concerts = []

    for table in tables:
        if len(table) < 5:
            continue
        headers = table[0]
        header_text = ' '.join(headers).lower()
        if 'date' not in header_text or 'venue' not in header_text:
            continue

        # Check this isn't a cancelled dates table or records table
        if 'reason' in header_text or 'organization' in header_text:
            continue

        # Determine the year from headers
        year_match = re.search(r'date \((\d{4})\)', header_text)
        if not year_match:
            year_match = re.search(r'dates? \((\d{4})\)', header_text)
        if not year_match:
            continue
        base_year = int(year_match.group(1))

        # Find column indices
        date_col = 0
        city_col = 1
        country_col = None
        venue_col = None

        for i, h in enumerate(headers):
            h_lower = h.lower()
            if 'country' in h_lower:
                country_col = i
            elif 'venue' in h_lower:
                venue_col = i

        if venue_col is None:
            continue

        last_city = ''
        last_country = ''
        last_venue = ''

        for row in table[1:]:
            if len(row) < 2:
                continue

            # Skip total rows
            if row[0].startswith('Total'):
                continue

            # Get date
            date_str = clean_text(row[date_col])
            if not date_str:
                continue

            # Parse month and day - handle various formats
            # "March 13", "March 14[c]", "March 31–April 2", etc.
            date_str_clean = re.sub(r'\[.*?\]', '', date_str)

            # Handle date ranges like "March 31–April 2" - take first date
            if '–' in date_str_clean or '-' in date_str_clean:
                # Take the first date in range
                parts = re.split(r'[–-]', date_str_clean)
                date_str_clean = parts[0].strip()

            date_match = re.match(r'(\w+)\s+(\d+)', date_str_clean)
            if not date_match:
                continue

            month_str = date_match.group(1)
            day = int(date_match.group(2))

            months = {'January':1,'February':2,'March':3,'April':4,'May':5,'June':6,
                      'July':7,'August':8,'September':9,'October':10,'November':11,'December':12}
            month = months.get(month_str)
            if not month:
                continue

            year = base_year
            iso_date = f"{year:04d}-{month:02d}-{day:02d}"

            # Get city
            if len(row) > city_col:
                city = clean_text(row[city_col])
                if city:
                    last_city = city

            # Get country
            if country_col is not None and len(row) > country_col:
                country = clean_text(row[country_col])
                if country:
                    last_country = country

            # Get venue
            if len(row) > venue_col:
                venue = clean_text(row[venue_col])
                if venue:
                    last_venue = venue

            if last_city and last_venue:
                country = last_country if last_country else 'United States'
                concerts.append({
                    'date': iso_date,
                    'tour': tour_name,
                    'country': country,
                    'city': last_city,
                    'venue': last_venue
                })

    return concerts

def parse_reputation_tour(tables):
    """Parse Reputation Stadium Tour."""
    concerts = []

    for table in tables:
        if len(table) < 5:
            continue
        headers = table[0]
        header_text = ' '.join(headers).lower()
        if 'date' not in header_text or 'venue' not in header_text:
            continue
        if 'award' in header_text or 'organization' in header_text:
            continue

        year_match = re.search(r'date[s]? \((\d{4})\)', header_text)
        if not year_match:
            continue
        base_year = int(year_match.group(1))

        date_col = 0
        city_col = 1
        country_col = None
        venue_col = None

        for i, h in enumerate(headers):
            h_lower = h.lower()
            if 'country' in h_lower:
                country_col = i
            elif 'venue' in h_lower:
                venue_col = i

        if venue_col is None:
            continue

        last_city = ''
        last_country = ''
        last_venue = ''

        for row in table[1:]:
            if len(row) < 2:
                continue
            if row[0].startswith('Total'):
                continue

            date_str = clean_text(row[date_col])
            if not date_str:
                continue

            # Handle ranges like "May 11–12", "June 8–9", "July 20–22", "Aug 31–Sep 1"
            date_str_clean = re.sub(r'\[.*?\]', '', date_str)

            # For ranges, expand into multiple dates
            if '–' in date_str_clean or '-' in date_str_clean:
                parts = re.split(r'[–-]', date_str_clean)
                first_part = parts[0].strip()
                second_part = parts[1].strip()

                # Parse first date
                first_match = re.match(r'(\w+)\s+(\d+)', first_part)
                if not first_match:
                    continue

                first_month_str = first_match.group(1)
                first_day = int(first_match.group(2))

                # Parse second date (may have month or not)
                second_match = re.match(r'(\w+)\s+(\d+)', second_part)
                if second_match:
                    second_month_str = second_match.group(1)
                    second_day = int(second_match.group(2))
                else:
                    second_month_str = first_month_str
                    second_day = int(second_part)

                months = {'January':1,'February':2,'March':3,'April':4,'May':5,'June':6,
                          'July':7,'August':8,'September':9,'October':10,'November':11,'December':12}

                first_month = months.get(first_month_str)
                second_month = months.get(second_month_str)

                if not first_month or not second_month:
                    continue

                # Process city/country/venue
                if len(row) > city_col:
                    city = clean_text(row[city_col])
                    if city:
                        last_city = city
                if country_col is not None and len(row) > country_col:
                    country = clean_text(row[country_col])
                    if country:
                        last_country = country
                if len(row) > venue_col:
                    venue = clean_text(row[venue_col])
                    if venue:
                        last_venue = venue

                # Add both dates
                for m, d in [(first_month, first_day), (second_month, second_day)]:
                    iso_date = f"{base_year:04d}-{m:02d}-{d:02d}"
                    if last_city and last_venue:
                        concerts.append({
                            'date': iso_date,
                            'tour': 'Reputation Stadium Tour',
                            'country': last_country if last_country else 'United States',
                            'city': last_city,
                            'venue': last_venue
                        })
            else:
                # Single date
                date_match = re.match(r'(\w+)\s+(\d+)', date_str_clean)
                if not date_match:
                    continue

                month_str = date_match.group(1)
                day = int(date_match.group(2))

                months = {'January':1,'February':2,'March':3,'April':4,'May':5,'June':6,
                          'July':7,'August':8,'September':9,'October':10,'November':11,'December':12}
                month = months.get(month_str)
                if not month:
                    continue

                iso_date = f"{base_year:04d}-{month:02d}-{day:02d}"

                if len(row) > city_col:
                    city = clean_text(row[city_col])
                    if city:
                        last_city = city
                if country_col is not None and len(row) > country_col:
                    country = clean_text(row[country_col])
                    if country:
                        last_country = country
                if len(row) > venue_col:
                    venue = clean_text(row[venue_col])
                    if venue:
                        last_venue = venue

                if last_city and last_venue:
                    concerts.append({
                        'date': iso_date,
                        'tour': 'Reputation Stadium Tour',
                        'country': last_country if last_country else 'United States',
                        'city': last_city,
                        'venue': last_venue
                    })

    return concerts

def parse_eras_tour(tables):
    """Parse The Eras Tour tables (2023 and 2024)."""
    concerts = []

    for table in tables:
        if len(table) < 5:
            continue
        headers = table[0]
        header_text = ' '.join(headers).lower()
        if 'date' not in header_text or 'venue' not in header_text:
            continue
        if 'guitar' in header_text or 'award' in header_text or 'organization' in header_text:
            continue

        year_match = re.search(r'date \((\d{4})\)', header_text)
        if not year_match:
            continue
        base_year = int(year_match.group(1))

        date_col = 0
        city_col = 1
        country_col = None
        venue_col = None

        for i, h in enumerate(headers):
            h_lower = h.lower()
            if 'country' in h_lower:
                country_col = i
            elif 'venue' in h_lower:
                venue_col = i

        if venue_col is None:
            continue

        last_city = ''
        last_country = ''
        last_venue = ''

        for row in table[1:]:
            if len(row) < 2:
                continue
            if row[0].startswith('Total'):
                continue

            date_str = clean_text(row[date_col])
            if not date_str:
                continue

            # Handle date ranges - expand them
            date_str_clean = re.sub(r'\[.*?\]', '', date_str)

            if '–' in date_str_clean or '-' in date_str_clean:
                parts = re.split(r'[–-]', date_str_clean)
                first_part = parts[0].strip()
                second_part = parts[1].strip()

                first_match = re.match(r'(\w+)\s+(\d+)', first_part)
                if not first_match:
                    continue

                first_month_str = first_match.group(1)
                first_day = int(first_match.group(2))

                second_match = re.match(r'(\w+)\s+(\d+)', second_part)
                if second_match:
                    second_month_str = second_match.group(1)
                    second_day = int(second_match.group(2))
                else:
                    second_month_str = first_month_str
                    second_day = int(second_part)

                months = {'January':1,'February':2,'March':3,'April':4,'May':5,'June':6,
                          'July':7,'August':8,'September':9,'October':10,'November':11,'December':12}

                first_month = months.get(first_month_str)
                second_month = months.get(second_month_str)

                if not first_month or not second_month:
                    continue

                if len(row) > city_col:
                    city = clean_text(row[city_col])
                    if city:
                        last_city = city
                if country_col is not None and len(row) > country_col:
                    country = clean_text(row[country_col])
                    if country:
                        last_country = country
                if len(row) > venue_col:
                    venue = clean_text(row[venue_col])
                    if venue:
                        last_venue = venue

                # Generate all dates in range
                for d in range(first_day, second_day + 1):
                    m = first_month if d <= 31 and (second_month == first_month or d >= first_day) else second_month
                    if first_month == second_month:
                        m = first_month
                    iso_date = f"{base_year:04d}-{m:02d}-{d:02d}"
                    if last_city and last_venue:
                        concerts.append({
                            'date': iso_date,
                            'tour': 'The Eras Tour',
                            'country': last_country if last_country else 'United States',
                            'city': last_city,
                            'venue': last_venue
                        })
            else:
                date_match = re.match(r'(\w+)\s+(\d+)', date_str_clean)
                if not date_match:
                    continue

                month_str = date_match.group(1)
                day = int(date_match.group(2))

                months = {'January':1,'February':2,'March':3,'April':4,'May':5,'June':6,
                          'July':7,'August':8,'September':9,'October':10,'November':11,'December':12}
                month = months.get(month_str)
                if not month:
                    continue

                iso_date = f"{base_year:04d}-{month:02d}-{day:02d}"

                if len(row) > city_col:
                    city = clean_text(row[city_col])
                    if city:
                        last_city = city
                if country_col is not None and len(row) > country_col:
                    country = clean_text(row[country_col])
                    if country:
                        last_country = country
                if len(row) > venue_col:
                    venue = clean_text(row[venue_col])
                    if venue:
                        last_venue = venue

                if last_city and last_venue:
                    concerts.append({
                        'date': iso_date,
                        'tour': 'The Eras Tour',
                        'country': last_country if last_country else 'United States',
                        'city': last_city,
                        'venue': last_venue
                    })

    return concerts


# Process each tour
all_concerts = []

# Fearless Tour
tables = extract_tables('/tmp/fearless.html')
fearless = parse_fearless_tour(tables)
# Filter to 2010 only
fearless_2010 = [c for c in fearless if c['date'].startswith('2010')]
all_concerts.extend(fearless_2010)
print(f"Fearless Tour 2010: {len(fearless_2010)} concerts")

# Speak Now World Tour
tables = extract_tables('/tmp/speak_now_world_tour.html')
speak_now = parse_generic_tour(tables, 'Speak Now World Tour')
all_concerts.extend(speak_now)
print(f"Speak Now World Tour: {len(speak_now)} concerts")

# The Red Tour
tables = extract_tables('/tmp/the_red_tour.html')
red = parse_generic_tour(tables, 'The Red Tour')
all_concerts.extend(red)
print(f"The Red Tour: {len(red)} concerts")

# The 1989 World Tour
tables = extract_tables('/tmp/the_1989_world_tour.html')
tour_1989 = parse_generic_tour(tables, 'The 1989 World Tour')
all_concerts.extend(tour_1989)
print(f"The 1989 World Tour: {len(tour_1989)} concerts")

# Reputation Stadium Tour
tables = extract_tables('/tmp/reputation_stadium_tour.html')
rep = parse_reputation_tour(tables)
all_concerts.extend(rep)
print(f"Reputation Stadium Tour: {len(rep)} concerts")

# The Eras Tour
tables = extract_tables('/tmp/the_eras_tour.html')
eras = parse_eras_tour(tables)
all_concerts.extend(eras)
print(f"The Eras Tour: {len(eras)} concerts")

# Filter to date range
all_concerts = [c for c in all_concerts if '2010-01-01' <= c['date'] <= '2025-05-01']

# Sort by date
all_concerts.sort(key=lambda x: x['date'])

# Remove duplicates (same date + city + venue)
seen = set()
unique = []
for c in all_concerts:
    key = (c['date'], c['city'], c['venue'])
    if key not in seen:
        seen.add(key)
        unique.append(c)
all_concerts = unique

print(f"\nTotal concerts: {len(all_concerts)}")

# Print some samples for debugging
for c in all_concerts[:5]:
    print(f"  {c['date']} | {c['tour']} | {c['country']} | {c['city']} | {c['venue']}")
print("  ...")
for c in all_concerts[-5:]:
    print(f"  {c['date']} | {c['tour']} | {c['country']} | {c['city']} | {c['venue']}")

# Generate markdown table
lines = []
lines.append("| Date | Concert's English Name | Host Country | Host City | Host Venue |")
lines.append("|------|----------------------|-------------|-----------|------------|")

for c in all_concerts:
    lines.append(f"| {c['date']} | {c['tour']} | {c['country']} | {c['city']} | {c['venue']} |")

output = '\n'.join(lines)

with open('/tmp/pinchbench/b9164626/agent_workspace/answer.txt', 'w') as f:
    f.write(output)

print(f"\nWritten {len(all_concerts)} rows to answer.txt")

