from html.parser import HTMLParser
import re

class TableExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tables = []
        self.current_table = []
        self.current_row = []
        self.current_cell = ''
        self.in_table = False
        self.in_row = False
        self.in_cell = False
        self.depth = 0
        self.skip_nested = 0

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag == 'table':
            cls = attrs_dict.get('class', '')
            if 'wikitable' in cls or 'sortable' in cls:
                if not self.in_table:
                    self.in_table = True
                    self.current_table = []
                    self.depth = 1
                else:
                    self.depth += 1
                    self.skip_nested += 1
        if self.in_table and not self.skip_nested:
            if tag == 'tr':
                self.in_row = True
                self.current_row = []
            if tag in ('td', 'th'):
                self.in_cell = True
                self.current_cell = ''

    def handle_endtag(self, tag):
        if self.in_table:
            if tag in ('td', 'th') and self.in_cell and not self.skip_nested:
                self.in_cell = False
                text = self.current_cell.strip()
                text = re.sub(r'\s+', ' ', text)
                self.current_row.append(text)
            if tag == 'tr' and self.in_row and not self.skip_nested:
                self.in_row = False
                if self.current_row:
                    self.current_table.append(self.current_row)
            if tag == 'table':
                if self.skip_nested > 0:
                    self.skip_nested -= 1
                else:
                    self.in_table = False
                    if self.current_table:
                        self.tables.append(self.current_table)
                self.depth -= 1

    def handle_data(self, data):
        if self.in_cell and not self.skip_nested:
            self.current_cell += data

